// PRIVATE in-process operator lifecycle. A trusted host must supply the original
// approval, observations and issued execution owners. This is not a shell run
// command, provider bootstrap, authorization shortcut, scheduler or resume API.
import fs from 'node:fs';
import {record} from '../evaluation/intake-v1.mjs';
import {cloneFreeze} from '../workflow/contracts.mjs';
import {createDurablePairedArmOwnerV1} from '../hosts/repository/durable-paired-arm-owner-v1.mjs';
import {inspectArmTrialDirectoryV1} from './paired-arm-inspect.mjs';

const fail=code=>{throw Object.assign(Error(code),{code});};
export function createPairedArmCommandOwnerV1(input,dependencies={signalSource:process,mainIo:fs,sidecarIo:fs,inspectDirectory:inspectArmTrialDirectoryV1}){
  // Injected inspection, like signal and IO methods, is a trusted test/host seam.
  const deps=record(dependencies,['signalSource','mainIo','sidecarIo','inspectDirectory']);
  const inspectDirectory=deps.inspectDirectory;if(typeof inspectDirectory!=='function')fail('ARM_COMMAND_INSPECTOR');
  const methods=Object.fromEntries(['on','removeListener','rawListeners'].map(name=>{
    const fn=deps.signalSource?.[name];
    if(typeof fn!=='function')fail('ARM_COMMAND_SIGNALS');
    return [name,fn.bind(deps.signalSource)];
  }));
  // The original constructor validates/captures inputs without callbacks, IO or
  // allocation. Reject invalid input before adding process signal listeners.
  const owner=createDurablePairedArmOwnerV1(input,{mainIo:deps.mainIo,sidecarIo:deps.sidecarIo});
  let state='READY',reason=null,firstSignal=null,setupStop=false,runIssued=false;
  let signalFailure=false,signalCleanup='NOT_INSTALLED',lastStopRequest=null;
  let retained=null,inspection=null,finalReport=null;
  function requestStop(...args){
    if(args.length)fail('ARM_COMMAND_ARGUMENTS');
    if(state!=='RUNNING')return Object.freeze({status:'REFUSED',reason:'ARM_COMMAND_NOT_STOPPABLE',authorizing:false});
    if(!runIssued){
      const status=setupStop?'ALREADY_REQUESTED':'REQUESTED';setupStop=true;
      lastStopRequest={phase:'SETUP',status};return Object.freeze({status,authorizing:false});
    }
    const response=owner.requestStop();
    lastStopRequest={phase:'RUNNER',status:response.status};return response;
  }
  const listeners=['SIGINT','SIGTERM'].map(signal=>[signal,()=>{
    if(state!=='RUNNING')return;
    firstSignal??=signal;
    try{requestStop();}catch{signalFailure=true;}
  }]);
  function inspect(...args){
    if(args.length)fail('ARM_COMMAND_ARGUMENTS');
    return finalReport??cloneFreeze({schemaVersion:'nisi-paired-arm-command-owner-v1',
      state,reason,firstSignal,setupStop,lastStopRequest,signalFailure,
      cleanup:{signals:signalCleanup,storage:retained?.cleanup??'NOT_OBSERVED'},
      retentionAcknowledged:retained?.recorded===true,inspectionObserved:inspection?.status==='OBSERVED',inspection,
      storageFailure:retained?.failure==='RUNNER_ARM_STORAGE_UNCONFIRMED'?'RUNNER_ARM_STORAGE_UNCONFIRMED':null,
      recorded:false,actualDispatchCount:null,authorizing:false,resumable:false,
      measurementVerified:false,causalClaim:false,promotionEligible:false,
      remoteExecutionStopped:'UNKNOWN'});
  }
  async function run(...args){
    if(args.length)fail('ARM_COMMAND_ARGUMENTS');
    if(state!=='READY')fail('ARM_COMMAND_ALREADY_RAN');
    state='RUNNING';let stage='SIGNALS';
    try{
      for(const [signal,listener] of listeners){
        methods.on(signal,listener);
        if(!methods.rawListeners(signal).includes(listener))fail('ARM_COMMAND_SIGNAL_INSTALL');
      }
      stage='RUN';
      // Store creation and initial retention can synchronously emit a signal
      // through trusted IO seams before the runner is stoppable. Latch it until
      // run() has returned its original promise; never discard a pre-run stop.
      const running=owner.run();runIssued=true;
      if(setupStop)requestStop();
      retained=await running;
      stage='INSPECTION';
      if(retained.main?.directory)inspection=inspectDirectory(retained.main.directory);
    }catch{
      reason=stage==='SIGNALS'?'ARM_COMMAND_SIGNAL_INSTALL':stage==='RUN'?
        'ARM_COMMAND_RUN_UNCONFIRMED':'ARM_COMMAND_INSPECTION_UNAVAILABLE';
    }finally{
      // Original run awaits the original runner and both store-close attempts.
      // Do not race it, reopen storage, write another FINAL or forward signals.
      signalCleanup='REMOVED';
      for(const [signal,listener] of listeners){
        try{
          methods.removeListener(signal,listener);
          if(methods.rawListeners(signal).includes(listener))signalCleanup='UNCONFIRMED';
        }catch{signalCleanup='UNCONFIRMED';}
      }
      state='FINISHED';
    }
    // Retention acknowledgement is independent of later byte inspection. An
    // observed final can never repair a failed or unconfirmed acknowledgement.
    const view=inspect();
    finalReport=cloneFreeze({...view,recorded:retained?.recorded===true&&!signalFailure&&
      signalCleanup==='REMOVED'&&reason===null&&view.inspectionObserved});
    return finalReport;
  }
  return Object.freeze({run,inspect,requestStop});
}

// PRIVATE read-only observation of both ledgers. No raw records or row identities.
import {isAbsolute} from 'node:path';
import {types} from 'node:util';
import {cloneFreeze} from '../workflow/contracts.mjs';
import {inspectPairedArmTrialV1} from '../history/paired-arm-reconciliation-v1.mjs';

const states=['NOT_STARTED','PREPARED_UNCONFIRMED','STARTED_INCOMPLETE','EXECUTOR_OBSERVED','COMPLETE'];
const reasons=new Set(['NO_MAIN_SCHEDULE','UNAVAILABLE_OR_CORRUPT_BYTES','MAIN_SEMANTICS_REFUSED',
  'CROSS_LEDGER_BINDING_OR_ORDER','NO_SIDECAR_HEADER','MISSING_SIDECAR_LINKS','UNFINISHED_OR_PARTIAL_PREFIX',
  'INSPECTION_UNAVAILABLE']);
const byteStates=new Set(['EMPTY','UNAVAILABLE','INCOMPLETE','PARTIAL_TAIL','CORRUPT','FINAL_PRESENT']);
const value=(x,key)=>{
  if(!x||typeof x!=='object'||types.isProxy(x))throw Error('INVALID_PROJECTION');
  const d=Object.getOwnPropertyDescriptor(x,key);
  if(!d||!Object.hasOwn(d,'value'))throw Error('INVALID_PROJECTION');return d.value;
};
function array(x,max){
  if(types.isProxy(x)||!Array.isArray(x)||Object.getPrototypeOf(x)!==Array.prototype)throw Error('INVALID_PROJECTION');
  const n=value(x,'length');if(!Number.isSafeInteger(n)||n<0||n>max||Reflect.ownKeys(x).length!==n+1)throw Error('INVALID_PROJECTION');
  return Array.from({length:n},(_,i)=>value(x,String(i)));
}
// Closed pure projection boundary: future/invalid states cannot silently vanish
// from aggregate counts while retaining an OBSERVED result.
export function projectArmTrialInspectionV1(result){
  let status='REFUSED',exitCode=2,mainByteStatus='NOT_OBSERVED',sidecarByteStatus='NOT_OBSERVED';
  let reason='INSPECTION_UNAVAILABLE',counts=null,missingLinks=null;
  try{
    if(value(result,'schemaVersion')!=='nisi-paired-arm-reconciliation-v1')throw Error('INVALID_PROJECTION');
    const kernelStatus=value(result,'status'),why=value(result,'reason');
    if(!['FINAL_CROSSLINKED','INCOMPLETE','REFUSED'].includes(kernelStatus)||!(why===null||reasons.has(why)))throw Error('INVALID_PROJECTION');
    const rows=array(value(result,'rows'),256),missing=array(value(result,'missing'),4096);
    const projected=Object.fromEntries(states.map(state=>[state,0]));
    for(const row of rows){const state=value(row,'state');if(!states.includes(state))throw Error('INVALID_PROJECTION');projected[state]++;}
    for(const entry of missing)if(!['START_LINKED','PHASE_OBSERVED'].includes(value(entry,'missing')))throw Error('INVALID_PROJECTION');
    const main=Object.getOwnPropertyDescriptor(result,'mainByteStatus'),side=Object.getOwnPropertyDescriptor(result,'sidecarByteStatus');
    const mainState=main?value(result,'mainByteStatus'):'NOT_OBSERVED',sideState=side?value(result,'sidecarByteStatus'):'NOT_OBSERVED';
    if(![...byteStates,'NOT_OBSERVED'].includes(mainState)||![...byteStates,'NOT_OBSERVED'].includes(sideState))throw Error('INVALID_PROJECTION');
    if(kernelStatus==='FINAL_CROSSLINKED'&&(mainState!=='FINAL_PRESENT'||sideState!=='FINAL_PRESENT'||why!==null||missing.length))throw Error('INVALID_PROJECTION');
    [status,exitCode]=kernelStatus==='FINAL_CROSSLINKED'?['OBSERVED',0]:kernelStatus==='INCOMPLETE'?['INCOMPLETE',1]:['REFUSED',2];
    mainByteStatus=mainState;sidecarByteStatus=sideState;reason=why;counts=projected;missingLinks=missing.length;
  }catch{/* Keep only a bounded refusal. Never invoke a getter or echo input. */}
  return cloneFreeze({schemaVersion:'nisi-cli-paired-arm-inspection-v1',status,exitCode,
    mainByteStatus,sidecarByteStatus,reason,counts,missingLinks,actualDispatchCount:null,
    sourceTrust:'UNAUTHENTICATED_LOCAL_BYTES',pastAcknowledgement:'UNKNOWN',remoteExecutionStopped:'UNKNOWN',
    candidateBytesRevalidated:false,measurementVerified:false,causalClaim:false,
    authorizing:false,resumable:false,promotionEligible:false});
}
export function inspectArmTrialDirectoryV1(directory){
  if(typeof directory!=='string'||!directory||directory.length>4096||directory.includes('\0')||!isAbsolute(directory))
    throw Object.assign(Error('NISI_CLI_ARGUMENTS'),{code:'NISI_CLI_ARGUMENTS'});
  return projectArmTrialInspectionV1(inspectPairedArmTrialV1({directory}));
}

// Pure bounded argument snapshot; no execution or approval is performed here.
import { isAbsolute } from 'node:path';
const invalid = () => { throw Object.assign(Error('NISI_CLI_ARGUMENTS'), { code: 'NISI_CLI_ARGUMENTS' }); };
export function parseNisiArguments(args) {
  if (!Array.isArray(args) || Object.getPrototypeOf(args) !== Array.prototype || args.length > 128) invalid();
  const descriptors = Object.getOwnPropertyDescriptors(args);
  if (Reflect.ownKeys(descriptors).length !== args.length + 1) invalid();
  const copy = []; let length = 0;
  for (let i = 0; i < args.length; i++) {
    const d = descriptors[i];
    if (!d || !Object.hasOwn(d, 'value') || !d.enumerable || typeof d.value !== 'string' || d.value.length > 8192) invalid();
    length += d.value.length; if (length > 65536) invalid(); copy.push(d.value);
  }
  const first = copy[0];
  const command = first === undefined || ['help', '--help', '-h'].includes(first) ? 'help'
    : ['version', '--version', '-v'].includes(first) ? 'version'
    : first === 'doctor' ? 'doctor' : first === 'demo' ? 'demo' : first === 'inspect' ? 'inspect'
    : first === 'inspect-trial' ? 'inspect-trial' : first === 'inspect-arm-trial' ? 'inspect-arm-trial'
    : first === 'inspect-trial-diagnostic' ? 'inspect-trial-diagnostic' : null;
  const withArgs = ['demo', 'inspect', 'inspect-trial', 'inspect-arm-trial', 'inspect-trial-diagnostic'];
  if (!command || (!withArgs.includes(command) && copy.length > 1)) invalid();
  if (['inspect', 'inspect-trial', 'inspect-arm-trial', 'inspect-trial-diagnostic'].includes(command)
    && (copy.length !== 2 || !copy[1] || copy[1].length > 4096 || copy[1].includes('\0'))) invalid();
  if (['inspect-trial', 'inspect-arm-trial', 'inspect-trial-diagnostic'].includes(command) && !isAbsolute(copy[1])) invalid();
  return Object.freeze({ command, args: Object.freeze(withArgs.includes(command) ? copy.slice(1) : []) });
}

// Import-pure dispatcher. The binary owns streams/exit status; the demo retains
// its existing approval, signal handling, model and candidate admission rules.
import { parseNisiArguments } from './arguments.mjs';
import { CLI_HELP, CLI_VERSION, errorOutput } from './text.mjs';

export async function runNisiCli(args) {
  try {
    const parsed = parseNisiArguments(args);
    if (parsed.command === 'help') return { exitCode: 0, stdout: CLI_HELP, stderr: '' };
    if (parsed.command === 'version') return { exitCode: 0, stdout: CLI_VERSION + '\n', stderr: '' };
    if (parsed.command === 'doctor') {
      const { collectNisiDoctor } = await import('./doctor.mjs');
      const report = await collectNisiDoctor();
      return { exitCode: report.exitCode, stdout: JSON.stringify(report, null, 2) + '\n', stderr: '' };
    }
    if (parsed.command === 'inspect') {
      const { inspectNisiRunDirectoryV1 } = await import('./inspect.mjs');
      const result = inspectNisiRunDirectoryV1(parsed.args[0]);
      // Exit zero is successful observation, never acceptance of the stored run.
      return { exitCode: 0, stdout: JSON.stringify(result, null, 2) + '\n', stderr: '' };
    }
    if (parsed.command === 'inspect-trial') {
      const { inspectTrialDirectoryV1 } = await import('./paired-trial-inspect.mjs');
      const result = inspectTrialDirectoryV1(parsed.args[0]);
      // Operational refusal is a bounded report; malformed usage stays stderr.
      return { exitCode: result.exitCode, stdout: JSON.stringify(result, null, 2) + '\n', stderr: '' };
    }
    if (parsed.command === 'inspect-arm-trial') {
      const { inspectArmTrialDirectoryV1 } = await import('./paired-arm-inspect.mjs');
      const result = inspectArmTrialDirectoryV1(parsed.args[0]);
      return { exitCode: result.exitCode, stdout: JSON.stringify(result, null, 2) + '\n', stderr: '' };
    }
    if (parsed.command === 'inspect-trial-diagnostic') {
      const { inspectTrialDiagnosticFileV1 } = await import('./paired-trial-diagnostic-inspect.mjs');
      const result = inspectTrialDiagnosticFileV1(parsed.args[0]);
      return { exitCode: result.exitCode, stdout: JSON.stringify(result, null, 2) + '\n', stderr: '' };
    }
    if (parsed.command !== 'demo') throw Object.assign(Error(), { code: 'NISI_CLI_ARGUMENTS' });
    const { runPrivateLiveDemo } = await import('../examples/repository-live-model.mjs');
    // Always require explicit external storage through the new CLI. The legacy
    // direct example retains its default; no installed/check-out marker fallback.
    const result = await runPrivateLiveDemo(parsed.args, { requireExternalState: true });
    if (![0, 1, 2].includes(result?.exitCode)) throw Object.assign(Error(), { code: 'NISI_CLI_RESULT' });
    return { exitCode: result.exitCode, stdout: JSON.stringify(result, null, 2) + '\n', stderr: '' };
  } catch (error) { return errorOutput(error); }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import {EventEmitter} from 'node:events';
import {pairedArmContext} from './helpers/paired-arm-owner-fixture.mjs';
import {createPairedArmCommandOwnerV1} from '../cli/paired-arm-command-owner.mjs';
import {inspectArmTrialDirectoryV1} from '../cli/paired-arm-inspect.mjs';

async function context(t,options={}){
  const parentDirectory=fs.mkdtempSync(path.join(os.tmpdir(),'nisi-arm-command-'));
  t.after(()=>fs.rmSync(parentDirectory,{recursive:true,force:true}));
  const c=await pairedArmContext(t,{...options,workspaceParentRoot:parentDirectory});
  const {retain:_a,retainAdmission:_b,...source}=c.input;
  const input={...source,parentDirectory},signalSource=new EventEmitter(),mainIo={...fs},sidecarIo={...fs};
  const inspectors={inspectDirectory:inspectArmTrialDirectoryV1};
  return {c,input,parentDirectory,signalSource,mainIo,sidecarIo,inspectors,
    create:()=>createPairedArmCommandOwnerV1(input,{signalSource,mainIo,sidecarIo,inspectDirectory:inspectors.inspectDirectory})};
}
const trialDirs=c=>fs.readdirSync(c.parentDirectory).filter(x=>x.startsWith('nisi-trial-'));
function cleanReport(report){
  assert(Object.isFrozen(report));assert.equal(report.remoteExecutionStopped,'UNKNOWN');
  assert.equal(report.authorizing,false);assert.equal(report.resumable,false);
  assert.equal(report.actualDispatchCount,null);assert.equal(report.measurementVerified,false);
  for(const forbidden of ['synthetic.author','synthetic.reviewer','fixture.owner','candidateText','ownerSetId','requestId','PRIVATE_SECRET'])
    assert(!JSON.stringify(report).includes(forbidden),forbidden);
}

test('original durable owner is single-use, projects bounded observations, preserves legacy trust flags',async t=>{
  const x=await context(t),owner=x.create();
  assert.equal(owner.inspect().state,'READY');assert.equal(owner.requestStop().status,'REFUSED');
  const result=await owner.run();cleanReport(result);
  assert.equal(result.recorded,true);assert.equal(result.retentionAcknowledged,true);
  assert.equal(result.inspection.status,'OBSERVED');assert.equal(x.c.requests.length,2);
  assert.equal(result.cleanup.storage,'CLOSED');assert.equal(result.cleanup.signals,'REMOVED');
  assert(!JSON.stringify(result).includes(x.parentDirectory));assert.strictEqual(owner.inspect(),result);
  assert.equal(owner.requestStop().status,'REFUSED');await assert.rejects(owner.run(),{code:'ARM_COMMAND_ALREADY_RAN'});
  assert.equal(x.signalSource.eventNames().length,0);assert.equal(trialDirs(x).length,1);
});

test('invalid input and call arguments do not install listeners or create trial storage',async t=>{
  const x=await context(t);let reads=0;
  Object.defineProperty(x.input,'reserve',{enumerable:true,get(){reads++;}});
  assert.throws(x.create);assert.equal(reads,0);assert.equal(x.signalSource.eventNames().length,0);assert.deepEqual(trialDirs(x),[]);
  const y=await context(t),owner=y.create();
  await assert.rejects(owner.run('unexpected'),{code:'ARM_COMMAND_ARGUMENTS'});
  assert.throws(()=>owner.inspect(1));assert.throws(()=>owner.requestStop(1));assert.equal(owner.inspect().state,'READY');
});

for(const signal of ['SIGINT','SIGTERM'])test(`setup ${signal} is latched through both listener boundaries`,async t=>{
  const x=await context(t),other=()=>{};x.signalSource.on(signal,other);
  x.signalSource.on=function(name,fn){EventEmitter.prototype.on.call(this,name,fn);this.emit(signal);return this;};
  const owner=x.create(),result=await owner.run();cleanReport(result);
  assert.equal(result.setupStop,true);assert.equal(result.firstSignal,signal);assert.equal(result.recorded,true);
  assert.equal(result.inspection.status,'OBSERVED');assert.equal(x.c.requests.length,0);
  assert.deepEqual(x.signalSource.rawListeners(signal),[other]);
});

for(const mode of ['throw-first','throw-second','silent'])test(`listener install ${mode} creates no stores and preserves unrelated listeners`,async t=>{
  const x=await context(t),other=()=>{};x.signalSource.on('SIGINT',other);
  x.signalSource.on=function(signal,fn){
    if(mode==='silent')return this;
    EventEmitter.prototype.on.call(this,signal,fn);
    if(signal===(mode==='throw-first'?'SIGINT':'SIGTERM'))throw Error('PRIVATE_SECRET');return this;
  };
  const result=await x.create().run();cleanReport(result);
  assert.equal(result.reason,'ARM_COMMAND_SIGNAL_INSTALL');assert.equal(result.recorded,false);
  assert.equal(result.inspection,null);assert.equal(result.cleanup.signals,'REMOVED');
  assert.equal(x.c.requests.length,0);assert.deepEqual(trialDirs(x),[]);
  assert.deepEqual(x.signalSource.rawListeners('SIGINT'),[other]);assert.equal(x.signalSource.listenerCount('SIGTERM'),0);
});

for(const lane of ['main','sidecar'])test(`${lane} store creation signal stops before dispatch`,async t=>{
  const x=await context(t),io=lane==='main'?x.mainIo:x.sidecarIo;let fired=false;
  io.openSync=(...args)=>{const fd=fs.openSync(...args);if(!fired){fired=true;x.signalSource.emit('SIGTERM');}return fd;};
  const result=await x.create().run();cleanReport(result);
  assert.equal(fired,true);assert.equal(result.setupStop,true);assert.equal(result.recorded,true);
  assert.equal(x.c.requests.length,0);assert.equal(result.inspection.status,'OBSERVED');
});

test('repeated and mixed signals during original execution request one cancellation with no oracle or redispatch',async t=>{
  let x,calls=0;
  x=await context(t,{onRequest(_request,response){
    calls++;x.signalSource.emit('SIGINT');x.signalSource.emit('SIGTERM');x.signalSource.emit('SIGINT');
    return new Response(JSON.stringify(response));
  }});
  const owner=x.create(),result=await owner.run();cleanReport(result);
  assert.equal(result.firstSignal,'SIGINT');assert.equal(calls,1);assert.equal(result.recorded,true);
  assert.equal(x.c.state.oracle.inspect().state,'NEW');assert.equal(result.remoteExecutionStopped,'UNKNOWN');
  const bytes=fs.readFileSync(path.join(x.parentDirectory,trialDirs(x)[0],'events.jsonl'));
  x.signalSource.emit('SIGTERM');assert.strictEqual(owner.inspect(),result);
  assert.deepEqual(fs.readFileSync(path.join(x.parentDirectory,trialDirs(x)[0],'events.jsonl')),bytes);
});

for(const [lane,marker] of [['main','"type":"SCHEDULE"'],['sidecar','"kind":"HEADER"'],
  ['sidecar','"kind":"PREPARED"'],['main','"type":"START_INTENT"'],
  ['sidecar','"kind":"PHASE_OBSERVED"'],['main','"type":"FINAL"'],['sidecar','"kind":"FINAL"']])
test(`signal during ${lane} retention ${marker} cannot overlap close`,async t=>{
  const x=await context(t),io=lane==='main'?x.mainIo:x.sidecarIo;let writing=false,triggered=false,overlap=false;
  io.writeSync=(...args)=>{writing=true;try{
    if(!triggered&&args[1].toString().includes(marker)){triggered=true;x.signalSource.emit('SIGTERM');}
    return fs.writeSync(...args);
  }finally{writing=false;}};
  io.closeSync=fd=>{if(writing)overlap=true;return fs.closeSync(fd);};
  const result=await x.create().run();cleanReport(result);
  assert.equal(triggered,true);assert.equal(overlap,false);assert.equal(result.recorded,true);
  assert.equal(result.firstSignal,'SIGTERM');assert.equal(result.cleanup.signals,'REMOVED');
});

for(const lane of ['main','sidecar'])test(`${lane} final close keeps handlers installed and uncertainty cannot become acknowledged`,async t=>{
  const x=await context(t),io=lane==='main'?x.mainIo:x.sidecarIo;let fileFd,closed=false;
  io.openSync=(...args)=>{const fd=fs.openSync(...args);if(args[0].endsWith('.jsonl'))fileFd=fd;return fd;};
  io.closeSync=fd=>{
    if(fd===fileFd){closed=true;assert.equal(x.signalSource.listenerCount('SIGINT'),1);
      assert.equal(x.signalSource.listenerCount('SIGTERM'),1);x.signalSource.emit('SIGINT');}
    fs.closeSync(fd);if(fd===fileFd)throw Error('PRIVATE_SECRET');
  };
  const result=await x.create().run();cleanReport(result);
  assert.equal(closed,true);assert.equal(result.recorded,false);assert.equal(result.retentionAcknowledged,false);
  assert.equal(result.cleanup.signals,'REMOVED');assert.equal(result.firstSignal,'SIGINT');
});

for(const lane of ['main','sidecar'])test(`${lane} creation failure retains evidence and never retries`,async t=>{
  const x=await context(t),io=lane==='main'?x.mainIo:x.sidecarIo;let opens=0;
  io.openSync=()=>{opens++;throw Error('PRIVATE_SECRET');};
  const owner=x.create(),result=await owner.run();cleanReport(result);
  assert.equal(result.recorded,false);assert.equal(x.c.requests.length,0);assert.equal(opens,1);
  assert.equal(result.cleanup.signals,'REMOVED');assert.equal(trialDirs(x).length,1);
  await assert.rejects(owner.run());assert.equal(opens,1);
});

for(const mode of ['throw','silent'])test(`listener removal ${mode} cannot report command recorded`,async t=>{
  const x=await context(t);
  x.signalSource.removeListener=function(signal,fn){
    if(mode==='throw'){EventEmitter.prototype.removeListener.call(this,signal,fn);throw Error('PRIVATE_SECRET');}
    return this;
  };
  const owner=x.create(),result=await owner.run();cleanReport(result);
  assert.equal(result.retentionAcknowledged,true);assert.equal(result.recorded,false);assert.equal(result.cleanup.signals,'UNCONFIRMED');
  x.signalSource.emit('SIGINT');assert.strictEqual(owner.inspect(),result);
  // Only this test's isolated fake emitter, never the process signal source.
  x.signalSource.removeAllListeners();
});

test('post-close missing bytes cannot erase historical ack or become accepted inspection',async t=>{
  const x=await context(t);let sideFd,sideFile;
  x.sidecarIo.openSync=(...args)=>{const fd=fs.openSync(...args);if(args[0].endsWith('.jsonl')){sideFd=fd;sideFile=args[0];}return fd;};
  x.sidecarIo.closeSync=fd=>{fs.closeSync(fd);if(fd===sideFd)fs.unlinkSync(sideFile);};
  const result=await x.create().run();cleanReport(result);
  assert.equal(result.retentionAcknowledged,true);assert.equal(result.recorded,false);assert.equal(result.inspectionObserved,false);
  assert.equal(result.inspection.status,'REFUSED');assert.equal(result.inspection.authorizing,false);
});

test('throwing inspector is captured once, cannot leak errors, and cannot erase historical ack',async t=>{
  const x=await context(t);let calls=0;
  x.inspectors.inspectDirectory=()=>{calls++;throw Error('PRIVATE_SECRET');};
  const owner=x.create();x.inspectors.inspectDirectory=()=>{throw Error('MUTATED_INSPECTOR');};
